import AddItems from "@/components/SettingsDialogs/AddItems.vue";
import AddCategory from "@/components/SettingsDialogs/AddCategory.vue";
import MasterCategory from "@/components/SettingsComponents/MasterCategory.vue";
import MasterItems from "@/components/SettingsComponents/MasterItems.vue";
import SnackBar from "@/components/SnackBar.vue";
export default {
  components: {
    MasterItems,
    MasterCategory,
    AddCategory,
    AddItems,
    SnackBar
  },
  data() {
    return {
      toggle_exclusive: "itemsMasters",
      componentCheck: 0,
      categoryKey: 0,
      itemKey: 0,
      categoriesAddition: false,
      ItemsAddition: false,
      SnackBarComponent: {}
    };
  },
  created() {},
  methods: {
    add_categories() {
      this.componentCheck = 1;
      this.categoriesAddition = true;
    },
    add_items() {
      this.componentCheck = 2;
      this.ItemsAddition = true;
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.ItemsAddition = false;
      this.categoriesAddition = false;
    },
    updatecategory() {
      this.categoryKey++;
    },
    updateItems() {
      this.itemKey++;
    },
    goBack() {
      this.$emit('backAction');
    }
  }
};
